const jsonData = pm.response.json();

pm.test("Response status code should be 200", () => {
    pm.response.to.have.status(200);
});

pm.test("Response should contain a list of users", () => {
    pm.expect(jsonData).to.be.an('array');
});

if (jsonData.length > 0) {
    pm.test("Array should not be empty or null", () => {
        pm.expect(jsonData).to.not.be.empty.and.not.null;
    });

    pm.test("Array should contain at least one user", () => {
        pm.expect(jsonData).to.have.lengthOf.at.least(1);
    });

    pm.test("Verify the first user details", () => {
        const user = jsonData[0];
        pm.expect(user).to.have.property("id", 1);
        pm.expect(user).to.have.property("name", "John Doe");
        pm.expect(user).to.have.property("email", "john@example.com");
        pm.expect(user).to.have.property("nickName", "John");
    });
} else {
    pm.test("Array is null or empty", function () {
        pm.expect.fail("Report as a bug.");
    });
}

pm.test("Pre-request: Generate a random user full name", () => {
    const firstName = pm.variables.replaceIn('{{$randomFirstName}}');
    const lastName = pm.variables.replaceIn('{{$randomLastName}}');
    const nickName = firstName;
    const fullName = `${firstName} ${lastName}`;

    // Set environment variables for the user full name and nick name
    pm.environment.set("test_user_fullName", fullName);
    pm.environment.set("test_user_nickName", nickName);

    // Verify set variables
    pm.expect(pm.environment.get("test_user_fullName")).to.equal(fullName);
    pm.expect(pm.environment.get("test_user_nickName")).to.equal(nickName);

});

pm.test("Pre-request: Generate user email and set as collection variable", () => {
    const d = new Date();
    const p = n => String(n).padStart(2, "0");
    const ts = `${d.getUTCFullYear()}${p(d.getUTCMonth() + 1)}${p(d.getUTCDate())}` +
        `${p(d.getUTCHours())}${p(d.getUTCMinutes())}${p(d.getUTCSeconds())}` +
        `${String(d.getUTCMilliseconds()).padStart(3, "0")}`;
    const userEmail = `testuser_${ts}@example.com`;

    // Set environment variable for the user email
    pm.environment.set("test_user_email", userEmail);

    // Verify set variables
    pm.expect(pm.environment.get("test_user_email")).to.equal(userEmail);

    console.log("Generated user email:", userEmail);
});

